/*
 * prog59_rule110.c
 *
 * Re‑implementation of the original binary (prog59_rule110) after
 * reverse‑engineering.  The program implements the elementary cellular
 * automaton “Rule 110”.
 *
 * Usage:
 *     prog59_rule110 <binary‑string> <steps>
 *
 *   <binary‑string>  – a non‑empty string of at most 60 characters,
 *                      each character must be ‘0’ or ‘1’.
 *   <steps>          – a non‑negative integer (decimal).  Values larger
 *                      than 200 are silently capped to 200.
 *
 * The program prints the initial configuration followed by the next
 * <steps> generations, one line per generation.  If any of the input
 * constraints is violated the program prints the line
 *
 *     INVALID_INPUT
 *
 * (followed by a newline) and exits.
 *
 * The implementation follows the logic discovered in the disassembly:
 *   • argument validation,
 *   • copying the initial row into a double‑buffer,
 *   • iterating <steps> times (printing the current row before each
 *     iteration, i.e. total lines = steps+1),
 *   • applying Rule 110 with a zero‑filled border.
 *
 * The rule table is stored in the order used by the original code:
 *   index = left*4 + right*2 + centre   (left = most‑significant bit)
 *   RULE110[index] = new cell value (0 or 1)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN   60          /* maximum length of the input string   */
#define MAX_STEPS 200         /* hard limit for the number of steps   */

/* Rule 110 table – index = left*4 + right*2 + centre */
static const char RULE110[8] = {
    0,  /* 000 -> 0 */
    1,  /* 010 -> 1 */
    1,  /* 001 -> 1 */
    1,  /* 011 -> 1 */
    0,  /* 100 -> 0 */
    1,  /* 110 -> 1 */
    1,  /* 101 -> 1 */
    0   /* 111 -> 0 */
};

/* Helper: print a row (array of '0'/'1') followed by a newline */
static void print_row(const char *row, size_t len)
{
    for (size_t i = 0; i < len; ++i)
        putchar(row[i]);
    putchar('\n');
}

/* Helper: validate that a string consists only of ‘0’ and ‘1’ */
static int is_binary_string(const char *s, size_t len)
{
    for (size_t i = 0; i < len; ++i)
        if (s[i] != '0' && s[i] != '1')
            return 0;
    return 1;
}

int main(int argc, char *argv[])
{
    /* ---------- argument count check ---------- */
    if (argc < 3) {
        puts("INVALID_INPUT");
        return 0;
    }

    /* ---------- read and validate the initial row ---------- */
    const char *input = argv[1];
    size_t len = strlen(input);

    if (len == 0 || len > MAX_LEN) {
        puts("INVALID_INPUT");
        return 0;
    }
    if (!is_binary_string(input, len)) {
        puts("INVALID_INPUT");
        return 0;
    }

    /* ---------- read and validate the number of steps ---------- */
    char *endptr;
    long steps_long = strtol(argv[2], &endptr, 10);

    if (*endptr != '\0') {               /* non‑numeric characters */
        puts("INVALID_INPUT");
        return 0;
    }
    if (steps_long < 0) {                /* negative value */
        puts("INVALID_INPUT");
        return 0;
    }

    int steps = (int)steps_long;
    if (steps > MAX_STEPS)               /* cap to the hard limit */
        steps = MAX_STEPS;

    /* ---------- double buffer for the rows ---------- */
    char row[2][MAX_LEN];                 /* two rows, each up to 60 cells */
    /* copy the initial configuration into row[0] */
    for (size_t i = 0; i < len; ++i)
        row[0][i] = input[i];
    /* initialise the rest of the buffer (not strictly needed) */
    for (size_t i = len; i < MAX_LEN; ++i)
        row[0][i] = '0';

    int cur = 0;      /* index of the row that currently holds the state */
    int nxt = 1;      /* index of the row we will write the next generation to */

    /* ---------- simulation ---------- */
    /* The program prints the initial configuration and then exactly
       <steps> further generations (total lines = steps+1). */
    for (int gen = 0; gen <= steps; ++gen) {
        /* print the current generation */
        print_row(row[cur], len);

        if (gen == steps)
            break;

        /* compute the next generation using Rule 110 */
        for (size_t i = 0; i < len; ++i) {
            int left   = (i == 0)      ? 0 : (row[cur][i - 1] - '0');
            int centre = row[cur][i]   - '0';
            int right  = (i + 1 == len) ? 0 : (row[cur][i + 1] - '0');

            int idx = left * 4 + right * 2 + centre;  /* as discovered */
            row[nxt][i] = RULE110[idx] + '0';
        }

        /* swap buffers */
        cur ^= 1;
        nxt ^= 1;
    }

    return 0;
}
